parameters.jsCode:
// Build the prompt from the ticket.
//
// Two deliberate choices here.
//
// 1. Only the fields that actually inform test design are sent: summary,
//    description, acceptance criteria, issue type, components and labels.
//    Sending the whole issue object wastes tokens and, more importantly,
//    sends reporter names, comment threads and internal links to a third
//    party for no benefit. Send the minimum the task needs.
//
// 2. Acceptance criteria are read from a custom field if present, because on
//    most boards that is where they live rather than in the description. The
//    field id differs per Jira instance - find yours at
//    /rest/api/3/field and change the constant below.

const CUSTOM_FIELD_ACCEPTANCE_CRITERIA = 'customfield_10100';

const issue = $input.first().json;
const fields = issue.fields || {};

// Jira Cloud returns descriptions in Atlassian Document Format, not plain
// text. Flatten it rather than stringifying the whole tree.
function adfToText(node) {
  if (!node) return '';
  if (typeof node === 'string') return node;
  if (node.type === 'text') return node.text || '';
  const children = node.content || [];
  const text = children.map(adfToText).join('');
  // Preserve paragraph and list-item breaks so bullet lists survive.
  return ['paragraph', 'listItem', 'heading'].includes(node.type) ? text + '\n' : text;
}

const description = typeof fields.description === 'string'
  ? fields.description
  : adfToText(fields.description);

const acceptanceCriteria = adfToText(fields[CUSTOM_FIELD_ACCEPTANCE_CRITERIA]);

const ticket = {
  key: issue.key,
  type: fields.issuetype ? fields.issuetype.name : 'Unknown',
  summary: fields.summary || '',
  description: description.trim(),
  acceptanceCriteria: acceptanceCriteria.trim(),
  components: (fields.components || []).map(c => c.name),
  labels: fields.labels || []
};

// Quality gate on the INPUT. A ticket with no description and no acceptance
// criteria cannot produce useful scenarios, and asking a model to invent them
// is how you end up with plausible nonsense in a Jira comment. Flag it back
// to the author instead.
const wordCount = (ticket.description + ' ' + ticket.acceptanceCriteria)
  .split(/\s+/).filter(Boolean).length;

ticket.tooThinToProcess = wordCount < 15;
ticket.wordCount = wordCount;

return [{ json: ticket }];

