  model: 'claude-sonnet-4-6',
  max_tokens: 2000,
  temperature: 0,
  system: $vars.gherkinSystemPrompt,
  messages: [
    {
      role: 'user',
      content: 'Ticket: ' + $json.key + '\nType: ' + $json.type + '\nSummary: ' + $json.summary + '\nComponents: ' + $json.components.join(', ') + '\nLabels: ' + $json.labels.join(', ') + '\n\nDescription:\n' + $json.description + '\n\nAcceptance criteria:\n' + ($json.acceptanceCriteria || '(none supplied)')
    }
  ]
}) }}

parameters.jsCode:
// Parse the response and gate it on quality.
//
// The point of this node: an AI step in a QA workflow that posts its output
// straight to Jira is worse than no workflow at all, because a plausible
// wrong scenario is harder to spot than an empty field. Everything below is
// a check that the output is structurally usable before a human is asked to
// review it.

const response = $input.first().json;
const ticket = $('Extract and check ticket').first().json;

// Anthropic returns content as an array of blocks.
const text = (response.content || [])
  .filter(block => block.type === 'text')
  .map(block => block.text)
  .join('\n')
  .trim();

if (!text) {
  throw new Error('Empty response from the model for ' + ticket.key);
}

// Strip a markdown fence if the model wrapped the output in one.
const gherkin = text
  .replace(/^```(?:gherkin|cucumber)?\s*/i, '')
  .replace(/```\s*$/, '')
  .trim();

// Structural checks. None of these judge whether the scenarios are GOOD -
// that is the reviewer's job - only whether they are valid Gherkin worth a
// reviewer's time.
const lines = gherkin.split('\n');
const checks = {
  hasFeature: /^\s*Feature:/m.test(gherkin),
  hasScenario: /^\s*(Scenario|Scenario Outline):/m.test(gherkin),
  hasGiven: /^\s*Given /m.test(gherkin),
  hasWhen: /^\s*When /m.test(gherkin),
  hasThen: /^\s*Then /m.test(gherkin),
  noPlaceholders: !/(TODO|TBD|<insert|xxx)/i.test(gherkin),
  noInventedIds: !/\b(REQ|AC)-\d+/.test(gherkin) || gherkin.includes(ticket.key)
};

const scenarioCount = (gherkin.match(/^\s*Scenario(?: Outline)?:/gm) || []).length;
const failed = Object.entries(checks).filter(([, ok]) => !ok).map(([name]) => name);

// Count negative and boundary coverage. A set of scenarios that is all happy
// path is the most common failure mode of AI-generated test design, so it is
// worth surfacing to the reviewer rather than leaving them to notice.
const negativeIndicators = (gherkin.match(/\b(invalid|rejected|refused|error|fails?|empty|blank|missing|unauthorised|unauthorized|expired|exceeds|negative|zero|maximum|minimum|boundary)\b/gi) || []).length;

return [{
  json: {
    issueKey: ticket.key,
    summary: ticket.summary,
    gherkin,
    scenarioCount,
    lineCount: lines.length,
    structuralChecksFailed: failed,
    passedStructuralChecks: failed.length === 0,
    negativeCoverageSignals: negativeIndicators,
    looksHappyPathOnly: negativeIndicators < 3,
    inputTokens: response.usage ? response.usage.input_tokens : null,
    outputTokens: response.usage ? response.usage.output_tokens : null
  }
}];

// Build the Jira comment.
//
// The comment is written to be read by a tester, and it is explicit that
// these are drafts. Framing matters: a comment that reads like finished work
// gets pasted into a test plan unreviewed, which is the exact outcome this
// workflow must not produce.

const d = $input.first().json;

let warnings = [];
if (!d.passedStructuralChecks) {
  warnings.push('Structural checks failed: ' + d.structuralChecksFailed.join(', ') + '. Treat with extra suspicion.');
}
if (d.looksHappyPathOnly) {
  warnings.push('Low negative and boundary coverage detected. The generated set looks happy-path heavy - add the negative cases yourself before using this.');
}

const warningBlock = warnings.length
  ? '\n{panel:bgColor=#fffae6}\n*Check before use*\n' + warnings.map(w => '- ' + w).join('\n') + '\n{panel}\n'
  : '';

const comment = [
  'h3. Draft Gherkin scenarios (AI-generated, unreviewed)',
  '',
  'Generated from the description and acceptance criteria on this ticket. ' +
  '*These are a starting point for test design, not test cases.* ' +
  'They have not been reviewed by a tester and they may miss domain rules that are not written on the ticket.',
  warningBlock,
  '{code:gherkin}',
  d.gherkin,
  '{code}',
  '',
  '----',
  '_Scenarios: ' + d.scenarioCount + ' | Lines: ' + d.lineCount + '_',
  '_Generated by n8n workflow "Jira ticket to Gherkin test scenarios"_',
  '',
  'Reviewer: delete this comment and replace it with the reviewed set, or reply with what it got wrong so the prompt can be improved.'
].join('\n');

return [{ json: { issueKey: d.issueKey, comment } }];

// The ticket was too thin to generate anything useful from.
//
// This branch exists because the alternative - generating scenarios from a
// one-line ticket - produces confident invented requirements. Asking the
// author for detail is the correct output, and it is also a genuinely useful
// shift-left nudge.

const t = $input.first().json;

const comment = [
  'h3. Not enough detail to draft test scenarios',
  '',
  'This ticket has ' + t.wordCount + ' words across its description and acceptance criteria, which is not enough to design tests from without inventing requirements.',
  '',
  'To draft scenarios automatically, the ticket needs:',
  '* what the user is trying to do',
  '* the acceptance criteria, including what should happen when things go wrong',
  '* any boundaries - limits, minimums, maximums, states the feature depends on',
  '',
  '_Generated by n8n workflow "Jira ticket to Gherkin test scenarios"_'
].join('\n');

return [{ json: { issueKey: t.key, comment } }];
